styles:
#special-sectionOverview *{
font-family: 'Segoe UI', Arial,Helvetica,sans-serif !important;
}

    .product-content {
    background-color: unset !important;
    }
    #hd #product-wrapper {
    margin-top: 40px !important;
    }
    #hd {
    font-family: inherit;
    }
    #product-header:before {
        background-image: url(https://dlcdnimgs.asus.com/websites/global/products/gi6ez0mqibqcpoj1/images/bg-header.jpg);
        background-size: cover;
    }

    #product-1:before {
        background-image: url(https://dlcdnimgs.asus.com/websites/global/products/gi6ez0mqibqcpoj1/images/bg-section1.jpg);
        background-size: cover;
    }

    #product-8:before {
        background-image: url(https://dlcdnimgs.asus.com/websites/global/products/gi6ez0mqibqcpoj1/images/bg-section8.jpg);
        background-size: cover;
    }

    #product-8 .product-text {
        width: 23%;
        top: 26%;
    }

    #product-7 .figure-group {
        top: 43.6%;
    }

    @media only screen and (max-width: 1440px) {
        #product-8 .product-text {
            width: 22%;
            right: 6%;
            top: 27%;
        }
    }

    @media only screen and (max-width: 768px) {
        #product-8 .product-text {
            width: auto;
            right: auto;
            top: auto;
        }
    }
